def is_emoji_codepoint(cp: int) -> bool:
    """Checks if a codepoint is an emoji or symbol character."""
    if cp in (0xFE0E, 0xFE0F):
        return True
    if cp in SMP_TO_PUA:
        return True
    if (0x1F000 <= cp <= 0x1FAFF):
        return True
    if (0x2600 <= cp <= 0x27BF) or (0x2300 <= cp <= 0x23FF) or (0x2B00 <= cp <= 0x2BFF):
        return True
    if (0xE000 <= cp <= 0xF8FF):
        return True
    return False

def format_ass_emoji(text: str, font_name: str = EMOJI_FONT_NAME) -> str:
    """
    Converts any emojis within text into font-tagged ASS subtitle fragments
    pointing to Noto Emoji TrueType font with BMP/PUA glyph mappings.
    Example:
      'YOU CHOOSE INTENTIONALLY 🚀' -> 'YOU CHOOSE INTENTIONALLY {\fnNoto Emoji Regular}{\fn}'
    """
    if not text:
        return ""

    out = []
    in_emoji = False

    for ch in text:
        cp = ord(ch)
        # Skip variation selectors (presentation modifiers) that cause blank glyph lookups
        if cp in (0xFE0E, 0xFE0F):
            continue

        if cp in SMP_TO_PUA:
            target_ch = chr(SMP_TO_PUA[cp])
            if not in_emoji:
                out.append(f"{{\\fn{font_name}}}")
                in_emoji = True
            out.append(target_ch)
        elif is_emoji_codepoint(cp):
            if not in_emoji:
                out.append(f"{{\\fn{font_name}}}")
                in_emoji = True
            out.append(ch)
        else:
            if in_emoji:
                out.append("{\\fn}")
                in_emoji = False
            out.append(ch)

    if in_emoji:
        out.append("{\\fn}")

    return "".join(out)
